B.bbz=new A.W("1. SOBRE A PLATAFORMA",null,B.e4,null,null,null,null,null,null,null,null,null,null)
B.eD=new A.y(!0,B.W,null,null,null,null,12.5,null,null,null,null,null,1.4,null,null,null,null,null,null,null,null,null,null,null,null,null)
B.baR=new A.W("O M\xe3o na Roda, operado pela Impetus Tecnologia, \xe9 uma plataforma de intermedia\xe7\xe3o e conveni\xeancia que conecta clientes tomadores de servi\xe7os a profissionais prestadores parceiros aut\xf4nomos.",null,B.eD,null,null,null,null,null,null,null,null,null,null)
B.b7P=new A.W("2. CUST\xd3DIA FINANCEIRA SEGURA (ESCROW)",null,B.e4,null,null,null,null,null,null,null,null,null,null)
B.bb7=new A.W("Todo valor pago (via PIX ou Cart\xe3o de Cr\xe9dito) \xe9 mantido em cust\xf3dia protegida pela plataforma. O valor s\xf3 \xe9 transferido para a carteira do prestador ap\xf3s a confirma\xe7\xe3o e aprova\xe7\xe3o expressa do servi\xe7o pelo cliente.",null,B.eD,null,null,null,null,null,null,null,null,null,null)
B.b9o=new A.W("3. TAXA DE SERVI\xc7O & REPASSE",null,B.e4,null,null,null,null,null,null,null,null,null,null)
B.bag=new A.W("A plataforma ret\xe9m uma taxa de intermedia\xe7\xe3o e seguran\xe7a de 10% sobre o valor total do chamado, repassando 90% l\xedquido ao prestador do atendimento.",null,B.eD,null,null,null,null,null,null,null,null,null,null)
B.b8H=new A.W("4. PRAZOS E PONTUALIDADE",null,B.e4,null,null,null,null,null,null,null,null,null,null)
B.b9N=new A.W("O prestador deve cumprir os prazos de deslocamento:\n\u2022 At\xe9 1 km de dist\xe2ncia: chegada em at\xe9 30 minutos.\n\u2022 Acima de 1 km: chegada em at\xe9 1 hora.\nO n\xe3o comparecimento sem justificativa enseja penalidades e cancelamento do chamado.",null,B.eD,null,null,null,null,null,null,null,null,null,null)
B.Xx=new A.y(!0,B.K,null,null,null,null,13,B.u,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null)
B.b82=new A.W("5. CANAL SEGURO & PROIBI\xc7\xc3O DE INTERMEDIA\xc7\xc3O EXTERNA",null,B.Xx,null,null,null,null,null,null,null,null,null,null)
B.bbf=new A.W("\xc9 estritamente proibido trocar contatos externos (n\xfameros de telefone, WhatsApp particular, chaves PIX externas ou redes sociais) pelo chat do aplicativo com o objetivo de negociar fora da plataforma. A infra\xe7\xe3o acarreta o bloqueio imediato e banimento definitivo das contas envolvidas.",null,B.eD,null,null,null,null,null,null,null,null,null,null)
B.b8r=new A.W("6. AVALIA\xc7\xd5ES E CONDUTA",null,B.e4,null,null,null,null,null,null,null,null,null,null)
